import json
from httpbin.core import app
client = app.test_client()

def test_delete_with_json_body_reflects_json_field():
    payload = {"key": "value"}
    r = client.delete(
        '/delete',
        data=json.dumps(payload),
        content_type='application/json'
    )
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['json'] == {"key": "value"}
    assert body['json'] != {"key": "other"}
    assert body['form'] == {}
    assert isinstance(body['data'], str)
    assert '"key"' in body['data']

test_delete_with_json_body_reflects_json_field()
